// Reason: chore(mac-baseline): dev-only synthetic HTTP benchmark server supporting Range and HEAD requests

/**
 * Lightweight synthetic HTTP server for benchmarking download engines.
 * Streams generated bytes on the fly at multi-gigabit speeds with zero disk overhead.
 *
 * Supported endpoints:
 * - /1gib or /bytes?size=1073741824 (1 GiB)
 * - /2gib or /bytes?size=2147483648 (2 GiB)
 * - /bytes?size=<N> (Custom byte size)
 */

const DEFAULT_PORT = parseInt(process.env.BENCHMARK_PORT || "8999", 10);
const CHUNK_SIZE = 128 * 1024; // 128 KiB generator buffer

// Pre-fill a fast pattern buffer
const PATTERN = new Uint8Array(CHUNK_SIZE);
for (let i = 0; i < CHUNK_SIZE; i++) {
  PATTERN[i] = (i * 31 + 17) & 0xff;
}

function resolveTotalSize(url: URL): number {
  if (url.searchParams.has("size")) {
    return parseInt(url.searchParams.get("size")!, 10);
  }
  if (url.pathname.includes("2gib")) {
    return 2 * 1024 * 1024 * 1024; // 2 GiB
  }
  if (url.pathname.includes("1gib")) {
    return 1024 * 1024 * 1024; // 1 GiB
  }
  return 1024 * 1024 * 1024; // Default 1 GiB
}

const server = Bun.serve({
  port: DEFAULT_PORT,
  fetch(req) {
    const url = new URL(req.url);

    if (url.pathname === "/health") {
      return new Response("OK", { status: 200 });
    }

    const totalSize = resolveTotalSize(url);
    const etag = `"bench-${totalSize}"`;

    if (req.method === "HEAD") {
      return new Response(null, {
        status: 200,
        headers: {
          "Content-Length": totalSize.toString(),
          "Accept-Ranges": "bytes",
          "ETag": etag,
          "Content-Type": "application/octet-stream",
          "Cache-Control": "no-store",
        },
      });
    }

    if (req.method === "GET") {
      const rangeHeader = req.headers.get("range");
      let start = 0;
      let end = totalSize - 1;
      let isPartial = false;

      if (rangeHeader) {
        const match = rangeHeader.match(/bytes=(\d+)-(\d*)/);
        if (match) {
          start = parseInt(match[1], 10);
          if (match[2]) {
            end = parseInt(match[2], 10);
          }
          isPartial = true;
        }

        if (start > end || start >= totalSize) {
          return new Response("Range Not Satisfiable", {
            status: 416,
            headers: {
              "Content-Range": `bytes */${totalSize}`,
            },
          });
        }
      }

      const contentLength = end - start + 1;
      let remaining = contentLength;

      const stream = new ReadableStream({
        pull(controller) {
          if (remaining <= 0) {
            controller.close();
            return;
          }
          const toSend = Math.min(remaining, CHUNK_SIZE);
          controller.enqueue(PATTERN.subarray(0, toSend));
          remaining -= toSend;
        },
      });

      const headers: Record<string, string> = {
        "Content-Length": contentLength.toString(),
        "Accept-Ranges": "bytes",
        "ETag": etag,
        "Content-Type": "application/octet-stream",
        "Cache-Control": "no-store",
      };

      if (isPartial) {
        headers["Content-Range"] = `bytes ${start}-${end}/${totalSize}`;
        return new Response(stream, { status: 206, headers });
      }

      return new Response(stream, { status: 200, headers });
    }

    return new Response("Method Not Allowed", { status: 405 });
  },
});

console.log(`[BENCHMARK_SERVER] Listening on http://127.0.0.1:${server.port}`);
